const rows = $input.all().map(i => i.json);
const urls = rows.map(r => (r.job_url || "").toString().trim().toLowerCase()).filter(Boolean);
const companyTitleKeys = rows
  .map(r => `${(r.company || "").toString().trim().toLowerCase()}|${(r.job_title || "").toString().trim().toLowerCase()}`)
  .filter(k => k !== "|");
return [{ json: { __type: "existing_keys", urls, companyTitleKeys } }];

const items = $input.all();
const seen = new Set();
const out = [];
