const all = $input.all().map(i => i.json);
const marker = all.find(j => j.__type === "existing_keys");
const jobs = all.filter(j => j.__type !== "existing_keys");
const urlSet = new Set(marker ? marker.urls : []);
const ctSet = new Set(marker ? marker.companyTitleKeys : []);
const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const j of jobs) {
  const urlKey = (j.job_url || "").trim().toLowerCase();
  const ctKey = `${(j.company || "").trim().toLowerCase()}|${(j.job_title || "").trim().toLowerCase()}`;
  if (urlKey && urlSet.has(urlKey)) continue;
  if (ctKey !== "|" && ctSet.has(ctKey)) continue;
  out.push({ json: { ...j, date_found: today } });
}
return out;

const REJECT_PHRASES = ["us only","u.s. only","canada only","uk only","u.k. only","eu only","europe only",
  "australia only","must be based in","must live in","must be authorized to work in","local work permit required",
  "hybrid","onsite","on-site","office required","remote within country only","fixed us hours","fixed eu hours"];
const KEEP_OVERRIDE_PHRASES = ["worldwide remote","global remote","work from anywhere","anywhere","apac remote",
  "international contractors accepted","contractor role","b2b contractor","hires via deel","hires via remote.com",
  "hires via oyster","eor supported","remote first","distributed team"];

return $input.all().map(item => {
  const j = item.json;
  const text = `${j.job_title} ${j.description} ${j.location_text}`.toLowerCase();
  const matchedReject = REJECT_PHRASES.filter(p => text.includes(p));
  const matchedKeep = KEEP_OVERRIDE_PHRASES.filter(p => text.includes(p));
  const hardPass = matchedReject.length === 0 || matchedKeep.length > 0;
  return { json: { ...j, hard_filter_pass: hardPass, hard_filter_reason: hardPass ? "" : `Rejected: ${matchedReject.join(", ")}` } };
});

return $input.all().map(item => ({ json: {
