const ASYNC_KEEP = ["async","asynchronous","flexible hours","flexible schedule","distributed team",
  "remote first","low meeting culture","work across time zones"];
const ASYNC_REJECT = ["strict 9 to 5","strict 9-to-5","fixed us hours","fixed est hours","fixed pst hours",
  "fixed cet hours","daily live calls required","must overlap full business day"];

return $input.all().map(item => {
  const j = item.json;
  const text = `${j.job_title} ${j.description}`.toLowerCase();
  const rejectHit = ASYNC_REJECT.some(p => text.includes(p));
  const keepHits = ASYNC_KEEP.filter(p => text.includes(p));
  let asyncLevel = "low";
  if (keepHits.includes("async") || keepHits.includes("asynchronous")) asyncLevel = "high";
  else if (keepHits.length >= 2) asyncLevel = "medium";
  else if (keepHits.length === 1) asyncLevel = "low_medium";
  return {
    json: {
      ...j,
      async_pass: !rejectHit,
      async_level: rejectHit ? "reject" : asyncLevel,
      async_reason: rejectHit ? "Fixed/strict working-hours requirement found in posting" : ""
    }
  };
});

return $input.all().map(item => ({ json: {
