const PRIMARY = ["data analyst","data scientist","junior data scientist","business intelligence analyst",
  "bi analyst","marketing analyst","performance marketing analyst","growth analyst","ai marketing specialist",
  "ai automation specialist","ai workflow consultant","martech analyst"];
const ADJACENT = ["creative strategist","marketing","data","automation","analytics","growth"];

return $input.all().map(item => {
  const j = item.json;
  const titleText = (j.job_title || "").toLowerCase();
  const descText = (j.description || "").toLowerCase();
  const isPrimary = PRIMARY.some(p => titleText.includes(p) || descText.includes(p));
  const isAdjacent = !isPrimary && ADJACENT.some(p => titleText.includes(p));
  return { json: { ...j, role_category: isPrimary ? "primary" : (isAdjacent ? "adjacent" : "other") } };
});

function buildWhyGoodFit(j) {
  const bits = [];
  if (j.role_category === "primary") bits.push("strong role match (data / AI marketing / BI / growth)");
  else if (j.role_category === "adjacent") bits.push("adjacent role match");
  if (j.async_level === "high") bits.push("clearly async, no fixed-hours risk");
  else if (j.async_level === "medium" || j.async_level === "low_medium") bits.push("flexible / distributed team culture");
  if (j.taiwan_eligible === "yes") bits.push("worldwide/APAC remote friendly, Taiwan OK");
  else if (j.taiwan_eligible === "unclear") bits.push("Taiwan eligibility unclear, needs manual check");
  return bits.join("; ") || "General remote fit";
}

return $input.all().map(item => {
  const j = item.json;
  let score = 0;
  const desc = (j.description || "").toLowerCase();

  // Taiwan eligibility (max 40)
  const clearlyWorldwide = ["worldwide remote", "work from anywhere", "global remote", "contractor"].some(p => desc.includes(p));
  const apacFriendly = desc.includes("apac remote") || desc.includes("apac");
  if (j.taiwan_eligible === "yes" && clearlyWorldwide) score += 40;
  else if (j.taiwan_eligible === "yes" && apacFriendly) score += 30;
  else if (j.taiwan_eligible === "yes") score += 30;
  else if (j.taiwan_eligible === "unclear" && j.location_risk !== "high") score += 20;

  // Async fit (max 25)
  if (j.async_level === "high") score += 25;
  else if (j.async_level === "medium") score += 20;
  else if (j.async_level === "low_medium") score += 15;
  else if (desc.includes("remote first")) score += 10;

  // Role fit (max 25)
  if (j.role_category === "primary") score += 25;
  else if (j.role_category === "adjacent") score += 15;

  // Salary fit (max 25) -- assumes listed figures are USD/month; adjust if a source lists annual figures
  const nums = (j.salary || "").replace(/[^0-9\-]/g, "").split("-").map(n => parseInt(n, 10)).filter(n => !isNaN(n));
  const maxSalary = nums.length ? Math.max(...nums) : 0;
  let salaryScore = 0;
  if (j.salary) salaryScore = 10;
  if (maxSalary >= 3000) salaryScore = 15;
  if (maxSalary >= 5000) salaryScore = 25;
  score += salaryScore;

  score = Math.min(score, 100);

  // Final decision logic (step 14)
  let decision = "reject";
  if (j.taiwan_eligible === "yes" && score >= 85 &&
      (j.async_level === "high" || j.async_level === "medium") &&
      j.location_risk === "low" &&
      (j.timezone_risk === "low" || j.timezone_risk === "medium")) {
    decision = "apply";
  } else if (j.taiwan_eligible === "unclear" && score >= 85 && j.location_risk === "medium") {
    decision = "manual_check";
  } else if (j.taiwan_eligible === "no" || j.location_risk === "high" || j.timezone_risk === "high" || score < 70) {
    decision = "reject";
  } else {
    decision = "manual_check";
  }

  return { json: { ...j, score, decision, why_good_fit: buildWhyGoodFit(j) } };
});

return $input.all().map(item => ({ json: {
