const original = $("Score >= 85?").item.json;
const resp = $json;
let text = "";
try { text = (resp.content && resp.content[0] && resp.content[0].text) || ""; } catch (e) { text = ""; }
return { json: { ...original, notes: `COVER LETTER DRAFT:\n\n${text}` } };

const all = $input.all().map(i => i.json);
const filteredEntry = all.find(x => x.filteredJobs);
const rejectedEntry = all.find(x => x.rejectedJobs);
const filtered = (filteredEntry && filteredEntry.filteredJobs) || [];
const rejected = (rejectedEntry && rejectedEntry.rejectedJobs) || [];

const top = [...filtered].sort((a, b) => b.score - a.score).slice(0, 8);
const manualCheck = filtered.filter(f => f.taiwan_eligible === "unclear" && f.score >= 85);

function reasonBucket(r) {
  const t = (r.reason || "").toLowerCase();
  if (t.includes("us only") || t.includes("u.s. only")) return "us_only";
  if (t.includes("eu only") || t.includes("europe only")) return "eu_only";
  if (t.includes("hybrid") || t.includes("onsite") || t.includes("on-site")) return "hybrid";
  if (t.includes("fixed") || t.includes("timezone") || t.includes("overlap") || t.includes("live calls")) return "timezone";
  return "other";
}
const counts = { us_only: 0, eu_only: 0, hybrid: 0, timezone: 0, other: 0 };
for (const r of rejected) counts[reasonBucket(r)]++;

let msg = "Daily Taiwan Eligible Async Remote Jobs\n\nTop jobs today:\n\n";
if (top.length === 0) {
  msg += "No jobs cleared the bar today.\n\n";
} else {
  top.forEach((j, i) => {
    msg += `${i + 1}. ${j.job_title}\n`;
    msg += `Company: ${j.company}\n`;
    msg += `Score: ${j.score}\n`;
    msg += `Taiwan eligible: ${j.taiwan_eligible}\n`;
    msg += `Reason: ${j.taiwan_reason || j.reason}\n`;
    msg += `Async level: ${j.async_level}\n`;
    msg += `Timezone risk: ${j.timezone_risk}\n`;
    msg += `Salary: ${j.salary || "Not listed"}\n`;
    msg += `Why it fits Jerry: ${j.why_good_fit}\n`;
    msg += `Apply link: ${j.job_url}\n\n`;
  });
}

msg += "Manual check:\n";
if (manualCheck.length === 0) {
  msg += "None today.\n\n";
} else {
  manualCheck.forEach(j => { msg += `- ${j.job_title} at ${j.company} (score ${j.score}) -- ${j.job_url}\n`; });
  msg += "\n";
}

msg += "Rejected summary:\n";
msg += `US only: ${counts.us_only}\n`;
msg += `EU only: ${counts.eu_only}\n`;
msg += `Hybrid/onsite: ${counts.hybrid}\n`;
msg += `Timezone risk: ${counts.timezone}\n`;
msg += `Other: ${counts.other}\n`;

return [{ json: { digest_message: msg, top_count: top.length, rejected_count: rejected.length } }];
